"""Q&A data part 1: platform basics, XDM and datasets, ingestion (streaming vs batch), identity and profile."""
TOPICS1 = []
def T(slug, title, desc, intro, items):
    TOPICS1.append(dict(slug=slug, title=title, desc=desc, intro=intro, items=items))

T("platform-basics", "AEP Basics: Platform, RTCDP, AJO & CJA Answers",
  "Short answers on Adobe Experience Platform: what it is, how Real-Time CDP, Journey Optimizer and CJA relate, sandboxes, Edge Network and architecture.",
  "Direct answers to the most common Adobe Experience Platform (AEP) questions, each with a link to the official Adobe documentation.",
  [("What is Adobe Experience Platform (AEP)?", "Adobe Experience Platform is Adobe's real-time customer data foundation. It standardises data with XDM schemas, stores it in datasets in a data lake, links identities, builds Real-Time Customer Profiles, evaluates audiences and activates them to destinations and Adobe applications.", ["aep", "blueprint"]),
   ("What is Real-Time CDP and how does it relate to AEP?", "Real-Time CDP (RTCDP) is an application built on Experience Platform. AEP supplies the data foundation (schemas, ingestion, identity, profile); RTCDP adds customer data platform capabilities, especially audience building and activation to marketing and advertising destinations.", ["aep", "blueprint"]),
   ("What is Adobe Journey Optimizer (AJO)?", "Adobe Journey Optimizer orchestrates real-time, cross-channel customer journeys on top of Experience Platform profiles and events. It handles journey design, messages, offer decisioning, consent-aware delivery and journey reporting.", ["ajo"]),
   ("What is Customer Journey Analytics (CJA)?", "Customer Journey Analytics analyses Experience Platform datasets, online and offline, joined on a person ID. It adds cross-channel reporting, data views, stitching and Analysis Workspace on data you already hold in AEP.", ["cja", "cja-faq"]),
   ("How is AEP different from a traditional data warehouse?", "A warehouse stores and queries data. AEP also standardises it in XDM, resolves identities, merges profiles in real time, evaluates audiences and activates them to channels, and enforces data governance labels and policies on activation.", ["aep", "learn-arch"]),
   ("What are the main components of AEP?", "Core components are the data lake and datasets, the schema registry (XDM), Identity Service, Real-Time Customer Profile, segmentation, the Edge Network for real-time collection and personalisation, Query Service, destinations and governance. Applications such as RTCDP, AJO and CJA sit on top.", ["aep", "blueprint"]),
   ("What is a sandbox in AEP and why use one?", "A sandbox is an isolated virtual environment inside one organisation. Use separate production and non-production sandboxes to test schema, dataset, audience and journey changes safely before promoting them.", ["aep", "xdm-import"]),
   ("How do I copy a schema from one sandbox to another?", "Use the Schema Registry import endpoint (or the sandbox tooling in the UI) to move a schema, with its field groups and data types, into another sandbox so it can be tested or promoted.", ["xdm-import"]),
   ("What is the Edge Network?", "The Edge Network is Adobe's globally distributed collection and personalisation layer. The Web SDK and Mobile SDK send events to it through a datastream, and it forwards data to Experience Platform and other Adobe services with low latency.", ["websdk", "edge-server"]),
   ("Which AEP component gives a single source of truth for customer profiles?", "Real-Time Customer Profile. It merges attribute and event fragments from Profile-enabled datasets, using the identity graph and merge policies, into one view per person.", ["merge", "guardrails"]),
   ("What are Profile guardrails?", "Guardrails are Adobe's documented limits and recommended practices for Real-Time Customer Profile data and segmentation, such as sizes, counts and performance recommendations. Check them before modelling data or enabling datasets for Profile.", ["guardrails"]),
   ("What is the Data Landing Zone?", "The Data Landing Zone is Adobe-provided cloud storage (Azure Blob) in each organisation where you can drop files for ingestion or receive exports, avoiding the need to set up your own storage for simple batch flows.", ["dlz"]),
   ("How should AEP be designed for several regions and brands?", "Separate brands and regions with sandboxes and role-based access, share one XDM model where it fits, plan identity namespaces and consent per region, apply data usage labels and policies, and check residency requirements with current Adobe documentation and your legal team.", ["blueprint", "rdc", "labels"]),
   ("Where can I learn AEP hands-on for free?", "Adobe publishes tutorials on Experience League, including the data architect and data engineer path and the Luma demo site. For guided labs and mentoring, see the Infinite360 Tech Academy programs.", ["learn-arch", "luma"]),
  ])

T("xdm-schemas-datasets", "XDM Schemas & Datasets: Questions and Answers",
  "Answers on XDM schemas, classes, field groups, datasets, identities, schema evolution and common modelling mistakes in Adobe Experience Platform.",
  "How to model data in Adobe Experience Platform using Experience Data Model (XDM) schemas and datasets.",
  [("What is XDM?", "Experience Data Model (XDM) is Adobe's standard framework for describing customer experience data. A schema built on XDM gives data a consistent structure and meaning across sources, applications and teams.", ["xdm-home"]),
   ("What is the difference between the XDM Individual Profile and XDM ExperienceEvent classes?", "Individual Profile describes attributes about a person (record data such as name or loyalty tier). ExperienceEvent describes time-stamped behaviour (time-series data such as page views, cart adds or transactions).", ["xdm-profile", "xdm-event"]),
   ("Which XDM class stores loan repayment or credit card transaction events?", "Use a schema based on XDM ExperienceEvent, because each repayment or transaction is a time-stamped event. Store durable customer attributes in an Individual Profile schema instead.", ["xdm-event"]),
   ("What is a field group?", "A field group is a reusable set of fields added to a schema, such as Personal Details or Commerce Details. Combine standard and custom field groups to compose a schema instead of redefining fields.", ["xdm-comp"]),
   ("Which field group captures a customer's age or birth date?", "The standard Individual Profile Personal Details field group holds person attributes such as birth date and name. Compute age from birth date rather than storing a value that goes stale.", ["xdm-profile"]),
   ("What is a data type in XDM?", "A data type is a reusable object definition, such as an identity or an address, that can be used by several fields or field groups. It keeps repeated structures consistent.", ["xdm-home"]),
   ("What is the tenant namespace?", "The tenant namespace (shown as an underscore plus your organisation's ID) is where custom fields you create live in a schema, separating them from standard Adobe fields. Plan a naming strategy for multi-brand organisations.", ["xdm-comp"]),
   ("What is a dataset?", "A dataset is a storage container for data that conforms to one schema. Data lands in the data lake, and if the dataset is enabled for Profile and Identity, it also feeds Real-Time Customer Profile.", ["xdm-home", "aep"]),
   ("What is the difference between record data and event data?", "Record data describes the current state of an entity and is typically updated (a customer profile). Event data records something that happened at a point in time and is appended (a purchase).", ["xdm-profile", "xdm-event"]),
   ("What is schema evolution?", "Schema evolution is how a schema changes over time. Once a schema is in use, changes are additive: you can add fields but not remove or change existing ones, so design carefully before ingesting data.", ["xdm-comp"]),
   ("How do I mark identities in a schema?", "Mark identity fields with an identity namespace and choose one as the primary identity where required. These marks let Identity Service build the graph and let Profile merge fragments.", ["xdm-identity"]),
   ("What are the most common XDM modelling mistakes?", "Frequent mistakes include ingesting without identities, using profile attributes for time-series data, over-nested custom structures, creating many one-off field groups instead of reusing standard ones, and enabling every dataset for Profile.", ["xdm-best", "guardrails"]),
   ("What is an ad-hoc schema?", "An ad-hoc schema is a lightweight schema created to support specific ingestion workflows, mainly for data such as identity or lookup sets, without the full governance of a standard schema.", ["xdm-adhoc"]),
   ("Where can I find industry data models?", "Adobe publishes industry data models, for example for retail, financial services and hospitality, as starting points for schema design. Review them before building custom structures.", ["xdm-industry"]),
   ("What are XDM field type constraints?", "Field type constraints are the data types and limits XDM allows for fields, such as strings, integers, dates and objects. Data that violates them can be rejected at ingestion.", ["xdm-constraints"]),
   ("What is a lookup dataset?", "A lookup is reference data kept separate from customer identity, such as a product catalogue or store list, that journeys and reports can join to without bloating events.", ["xdm-best"]),
  ])

_S = [  # streaming vs batch deep-dive (internals described conservatively; verify against current Adobe documentation)
 ("Why is streaming ingestion not always real-time at the Profile level?", "Streaming ingestion lands data with low latency, but updating Real-Time Customer Profile is a downstream, asynchronous process that includes validation, identity linking, merge-policy application and segment evaluation. Plan for near-real-time, not instant, Profile updates.", ["stream", "stream-learn"]),
 ("Can batch ingestion update Real-Time Customer Profile faster than streaming?", "Sometimes for large volumes. Batch jobs process records in bulk and can finish quickly when streaming is throttled or queued, but each batch has its own scheduling and completion time. Measure both paths with your own data.", ["batch", "stream"]),
 ("Why can two streaming events with the same timestamp appear in Profile at different times?", "Event time is not processing order. Each event passes asynchronously through identity and Profile processing, and load and queueing differ, so visibility depends on processing, not on the timestamp.", ["stream-learn"]),
 ("What happens if the same XDM ExperienceEvent is ingested by both streaming and batch?", "Both copies can exist in the data lake, and Profile may hold both events unless you control uniqueness. Send a stable unique event _id and avoid ingesting the same event through two paths.", ["xdm-event", "stream"]),
 ("Is Profile ingestion guaranteed exactly-once?", "Design as if delivery is at-least-once. Failures can lead to retries, so make events idempotent with unique event identifiers and check results in monitoring rather than assuming exactly-once behaviour.", ["stream", "guardrails"]),
 ("What is the lifecycle of a streaming event from the edge to query?", "A typical path is collection (SDK or API), Edge or streaming validation against the schema, write to the data lake, identity and Profile processing if the dataset is Profile-enabled, then availability in Query Service. Exact timings vary and are not guaranteed.", ["stream", "query"]),
 ("Why does streaming ingestion enforce the schema so strictly?", "Streaming data affects Profile, audiences and journeys almost immediately, so wrong types or missing required fields are rejected at the point of entry. Batch records can be reviewed after the fact in batch failure reports.", ["stream", "xdm-constraints"]),
 ("How does identity stitching differ between batch and streaming?", "Both feed the same identity graph. Streaming links identities incrementally as events arrive; batch brings many identifiers in one file, so links appear when the batch completes.", ["stream", "batch"]),
 ("Which services are involved only in streaming ingestion?", "Streaming through the Web SDK or Mobile SDK uses the Edge Network and datastreams, and streaming APIs accept HTTP records. Batch uses files, sources and the batch ingestion API. Both end in the data lake.", ["websdk", "stream", "batch"]),
 ("How is back-pressure handled differently in streaming and batch?", "Streaming sources can be throttled or queued when limits are reached, so senders should retry safely. Batch jobs are queued and processed as capacity allows, trading latency for throughput.", ["stream", "batch"]),
 ("What conditions must be met for a streaming event to update Profile?", "The dataset must be enabled for Profile, the schema should carry a valid identity, the data must pass schema validation, and consent and governance rules must allow the use. Missing any of these can leave the event only in the data lake.", ["enable-upsert", "xdm-identity", "guardrails"]),
 ("Why can a streaming event be ingested but not appear in Real-Time Profile?", "Common reasons: dataset not Profile-enabled, no identity on the record, record rejected or partially failed, processing not finished yet, merge policy or consent rules excluding it, or guardrail limits reached.", ["monitor", "guardrails"]),
 ("How does identityMap size affect streaming Profile ingestion?", "More identities per record means more graph work per event. Keep identityMap to the identifiers you actually need for stitching and activation, and avoid sending large numbers of low-value IDs.", ["xdm-identity", "guardrails"]),
 ("How do merge policies behave for streaming versus batch data?", "A merge policy decides which value wins when sources conflict, using rules such as timestamp order or dataset precedence. It applies the same way to both paths; what differs is when updates arrive and are processed.", ["merge"]),
 ("What happens if an event arrives with a new identity namespace that is not primary?", "The identity is stored and can link to others in the graph, but only the primary identity determines how the record is keyed. A non-primary identity helps stitching without becoming the profile key.", ["xdm-identity"]),
 ("What is the difference between Edge and hub streaming ingestion?", "Edge ingestion (Web SDK, Mobile SDK) is optimised for low-latency collection and same-session personalisation. Hub streaming (for example streaming HTTP APIs) prioritises reliable ingestion into datasets. Check current latency guidance in Adobe's streaming documentation.", ["stream", "stream-learn"]),
 ("Why are Edge Network events sometimes delayed in Profile visibility?", "The Edge accepts events immediately, but Profile visibility depends on downstream identity, merge and Profile Store processing, which runs asynchronously.", ["stream-learn", "websdk"]),
 ("How does deduplication behave at the Edge versus Profile ingestion?", "Do not rely on automatic event deduplication. Prevent duplicates by sending a unique event _id, avoiding double sends from client and server, and removing duplicates in data design rather than at Profile.", ["xdm-event", "websdk-track"]),
 ("Streaming shows success in the API but Profile count is unchanged. How do I debug?", "Check in order: the HTTP response and Debugger or Assurance output, schema validation errors, whether the dataset is Profile-enabled, identities present, dataflow and ingestion monitoring, then merge policy and consent filters.", ["debugger", "assurance", "monitor"]),
 ("Batch updates Profile but streaming for the same schema does not. What could be wrong?", "Likely causes are datastream configuration pointing to the wrong sandbox or dataset, the Web SDK not mapped to the datastream in Tags, missing identity in streamed events, or schema or consent differences between the two paths.", ["websdk-install", "datastream-prep", "monitor"]),
 ("What happens if a streaming payload is valid JSON but violates the schema?", "It can be rejected or partially processed. Valid JSON is not enough: field types, required fields and constraints must match the schema, otherwise Profile and audiences may not update.", ["xdm-constraints", "stream"]),
 ("How are partial failures handled in batch versus streaming?", "Streaming returns a result per request, so senders handle failures and retries. Batch reports failed records per batch and may complete with some records rejected, which you then correct and reload.", ["batch", "monitor"]),
 ("How do late-arriving events affect Profile and segmentation?", "Late events can be accepted into the data lake and Profile, but audience results already computed may not change until the next evaluation. Time-window rules are sensitive to late data, so measure how late events occur.", ["seg-stream", "xdm-event"]),
 ("Why can a streaming event trigger a journey but not yet update Profile attributes?", "Journeys can react to the event itself, while Profile attribute updates follow through identity and merge processing. Do not read Profile attributes in the same moment you trigger from the event.", ["ajo", "stream-learn"]),
 ("How does streaming ingestion affect edge versus batch segmentation?", "Edge segmentation evaluates rules at the Edge for same-page personalisation using data collected there. Batch segmentation evaluates all profiles on a schedule, so it sees streamed data only after the next run.", ["seg-edge", "seg-stream"]),
 ("Can a streaming event update a computed attribute immediately?", "No guarantee. Computed attributes are calculated by a service and refresh on their own cadence, so treat them as derived values with some delay.", ["computed"]),
 ("How does streaming ingestion affect segment qualification latency?", "Streaming segmentation can qualify profiles shortly after events arrive for eligible rules; batch segments qualify only when the scheduled evaluation runs, which can take hours to a day.", ["seg-stream"]),
 ("Why can batch be more stable than streaming at very high throughput?", "Batch processes data in controlled jobs and resolves work in bulk, while streaming must handle per-event limits and throttling. For very large histories, load in batch and reserve streaming for events that need speed.", ["stream", "batch", "guardrails"]),
 ("What state and memory challenges come with streaming Profile ingestion?", "Streaming Profile processing must keep identity and merge state current for every event, which is why Adobe documents limits and recommends keeping schemas, identities and Profile-enabled datasets lean.", ["guardrails"]),
 ("What are the limits of streaming Profile ingestion and how do I design around them?", "Limits include throughput, identity and merge cost, and documented guardrails. Design around them by streaming only decision-critical events, keeping identities simple, minimising Profile-enabled datasets and moving history to batch.", ["guardrails", "stream"]),
 ("Is event ordering guaranteed in streaming ingestion?", "Do not assume it. Events carry timestamps, and conflict resolution uses merge policy rules, so out-of-order events can cause temporary inconsistencies before profiles settle.", ["stream", "merge"]),
 ("How does AEP resolve conflicting attribute updates from batch and streaming?", "By merge policy rules such as timestamp ordering or dataset precedence, not by ingestion method. Define a custom merge policy if the default timestamp-based behaviour does not match your system of record.", ["merge"]),
 ("What happens if an older event ingested later overwrites a newer attribute?", "Under a timestamp-based policy the newer timestamp should win, but a dataset-precedence policy can let a preferred source win regardless. Choose the policy deliberately and test with out-of-order data.", ["merge"]),
 ("What is the difference between time-series and snapshot conflicts?", "Time-series (event) data is appended and keeps history, so conflicts rarely overwrite. Snapshot (profile attribute) data has one current value, so conflicting sources need merge rules.", ["xdm-event", "xdm-profile", "merge"]),
 ("When should I avoid streaming ingestion for Profile updates?", "Avoid it for high-volume, non-urgent data, history loads, data that changes rarely, out-of-order sources and cases with strict governance review. Use batch there and stream only what needs minutes-level reaction.", ["stream", "batch"]),
 ("How would I design a hybrid batch and streaming strategy for a bank?", "Stream login, payment and application-status events that drive journeys and risk suppression; batch rarely changing data such as KYC attributes, product holdings and rates. Combine both in segments and use merge policies to prefer the system of record.", ["stream", "batch", "merge"]),
 ("How do I keep Profile consistent when several systems stream updates?", "Name a system of record per attribute, standardise identity namespaces across sources, use dataset-precedence merge policies where needed, and validate with governance and monitoring.", ["merge", "xdm-identity"]),
 ("Which schema design mistakes break streaming Profile ingestion at scale?", "Missing primary identities, complex deeply nested custom structures, putting time-series data in profile schemas, creating many custom field groups instead of standard ones and too many Profile-enabled datasets.", ["xdm-best", "guardrails"]),
 ("How does Profile fragmentation happen and how is it fixed?", "Fragmentation happens when pieces of one customer's data are not linked because identities or namespaces differ across sources. Fix it with a consistent identity strategy, shared namespaces and a common identifier such as a CRM ID.", ["xdm-identity", "merge"]),
 ("Why does enabling Profile on too many streaming schemas hurt performance?", "Each Profile-enabled dataset adds identity, merge and storage work per record. Enable Profile only where the data is needed for segmentation or personalisation.", ["guardrails"]),
 ("What is the difference between ingested and activated data?", "Ingested data is what the platform stores. Activated data is the governed subset exported to a destination or used by an application, after consent and data usage policies are applied.", ["labels", "dest-types"]),
]
T("ingestion-streaming-vs-batch", "AEP Streaming vs Batch Ingestion: 42 Answers",
  "Answers on AEP streaming and batch ingestion: Profile latency, ordering, deduplication, identity stitching, merge policy, limits and hybrid designs.",
  "Practical answers on streaming versus batch ingestion in Adobe Experience Platform. Internal timings are not guaranteed by Adobe, so test with your own data and check the linked documentation.",
  _S)

T("identity-profile", "AEP Identity & Real-Time Profile: Answers",
  "Answers on AEP identity namespaces, the identity graph, ECID, merge policies, union schema, linked identities and troubleshooting missing identifiers.",
  "How identity resolution and Real-Time Customer Profile work in Adobe Experience Platform.",
  [("What does Identity Service do?", "Identity Service links identifiers that belong to the same person into an identity graph. Real-Time Customer Profile uses that graph to decide which data fragments to merge into one profile.", ["xdm-identity", "merge"]),
   ("What is an identity namespace?", "A namespace labels the type of an identifier, such as ECID, Email, Phone or a custom CRM ID. Typed namespaces keep unrelated identifiers from being confused with each other.", ["xdm-identity"]),
   ("What is the ECID?", "The Experience Cloud ID (ECID) is the device or browser identifier created by Adobe's collection libraries. It is anonymous until a known identity such as a login is linked to it.", ["websdk-ecid"]),
   ("What is the primary identity?", "The primary identity is the field a schema designates as the key for a record, for example a CRM ID for profile data or the ECID for web events. Choose one deliberately.", ["xdm-identity"]),
   ("How does AEP merge a customer's updated email from CRM into the profile?", "The record carries identities that link to the existing profile through the identity graph. The merge policy then decides which email value wins when sources conflict.", ["merge", "xdm-identity"]),
   ("How can I merge multiple account IDs under one customer?", "Ingest them with a shared linking identifier, for example a CRM or customer ID in a namespace common to all sources, so Identity Service connects the accounts into one graph.", ["xdm-identity"]),
   ("How do I see all identities linked to a customer?", "Open the profile in the Profiles area and review its linked identities, then open the identity graph viewer for the selected identity and namespace.", ["aep"]),
   ("Some profiles are missing loyalty IDs. Where do I check?", "Check the schema identity marking and namespace, whether the source dataset sends the loyalty ID, the identity map on sample profiles and whether the dataset is Profile-enabled.", ["xdm-identity", "monitor"]),
   ("What is a merge policy?", "A merge policy defines how data from several datasets combines in a profile when values conflict, for example by timestamp or by giving one dataset precedence, and which identity graph is used.", ["merge"]),
   ("What is the difference between timestamp ordered and dataset precedence merge policies?", "Timestamp ordered lets the most recently updated value win. Dataset precedence ranks sources, so a trusted system of record can win even when an older timestamp.", ["merge"]),
   ("Which source should win for regulated attributes such as occupation?", "Prefer the system of record, usually KYC for regulated customer data, using dataset precedence in the merge policy, and document that decision.", ["merge"]),
   ("What is the union schema?", "The union schema is the combined view of all fields from schemas of the same class that are enabled for Profile. It is what audiences and profile lookups read from.", ["union"]),
   ("What is a computed attribute?", "A computed attribute is a derived value calculated from events, such as lifetime purchases, and stored on the profile for use in audiences. It refreshes on the service's own schedule.", ["computed"]),
   ("What are profile fragments?", "A fragment is the piece of a customer's data that came from one dataset or record. Profile merges fragments into the single profile view.", ["merge", "guardrails"]),
   ("How does graph-based stitching in CJA relate to AEP identity?", "CJA's graph-based stitching uses identity graph information to connect anonymous and known activity across devices when reporting, separate from how profiles merge in Real-Time Customer Profile.", ["cja-stitch"]),
   ("Which AEP service gives me a single customer view of merged attributes?", "Real-Time Customer Profile, which merges attributes and events from several sources using identity and merge policies.", ["merge"]),
  ])
